def process_create_collection(
    request: Request, tenant: str, database: str, raw_body: bytes
) -> CollectionModel:
    create = validate_model(CreateCollection, orjson.loads(raw_body))
    if not create.configuration:
        if create.metadata:
            configuration = (
                create_collection_configuration_from_legacy_collection_metadata(
                    create.metadata
                )
            )
        else:
            configuration = None
    else:
        configuration = load_create_collection_configuration_from_json(
            create.configuration
        )

    # NOTE(rescrv, iron will auth):  Implemented.
    self.sync_auth_request(
        request.headers,
        AuthzAction.CREATE_COLLECTION,
        tenant,
        database,
        create.name,
    )

    self._set_request_context(request=request)

    add_attributes_to_current_span({"tenant": tenant})

    return self._api.create_collection(
        name=create.name,
        configuration=configuration,
        metadata=create.metadata,
        get_or_create=create.get_or_create,
        tenant=tenant,
        database=database,
    )

def process_create_collection(
    request: Request, tenant: str, database: str, raw_body: bytes
) -> CollectionModel:
    create = validate_model(CreateCollection, orjson.loads(raw_body))
    configuration = (
        CreateCollectionConfiguration()
        if not create.configuration
        else load_create_collection_configuration_from_json(
            create.configuration
        )
    )

    (
        maybe_tenant,
        maybe_database,
        # NOTE(rescrv, iron will auth):  v1
    ) = self.sync_auth_and_get_tenant_and_database_for_request(
        request.headers,
        AuthzAction.CREATE_COLLECTION,
        tenant,
        database,
        create.name,
    )
    if maybe_tenant:
        tenant = maybe_tenant
    if maybe_database:
        database = maybe_database

    return self._api.create_collection(
        name=create.name,
        configuration=configuration,
        metadata=create.metadata,
        get_or_create=create.get_or_create,
        tenant=tenant,
        database=database,
    )

def process_update_collection(
    request: Request, collection_id: str, raw_body: bytes
) -> None:
    update = validate_model(UpdateCollection, orjson.loads(raw_body))
    # NOTE(rescrv, iron will auth):  v1
    self.sync_auth_and_get_tenant_and_database_for_request(
        request.headers,
        AuthzAction.UPDATE_COLLECTION,
        None,
        None,
        collection_id,
    )
    configuration = (
        None
        if not update.new_configuration
        else load_update_collection_configuration_from_json(
            update.new_configuration
        )
    )
    return self._api._modify(
        id=_uuid(collection_id),
        new_name=update.new_name,
        new_metadata=update.new_metadata,
        new_configuration=configuration,
    )

async def add_v1(
    self,
    request: Request,
    collection_id: str,
) -> bool:
    try:

        def process_add(request: Request, raw_body: bytes) -> bool:
            add = validate_model(AddEmbedding, orjson.loads(raw_body))
            # NOTE(rescrv, iron will auth):  v1
            self.sync_auth_and_get_tenant_and_database_for_request(
                request.headers,
                AuthzAction.ADD,
                None,
                None,
                collection_id,
            )
            return self._api._add(
                collection_id=_uuid(collection_id),
                ids=add.ids,
                embeddings=cast(
                    Embeddings,
                    convert_list_embeddings_to_np(add.embeddings)
                    if add.embeddings
                    else None,
                ),
                metadatas=add.metadatas,  # type: ignore
                documents=add.documents,  # type: ignore
                uris=add.uris,  # type: ignore
            )

        return cast(
            bool,
            await to_thread.run_sync(
                process_add,
                request,
                await request.body(),
                limiter=self._capacity_limiter,
            ),
        )
    except InvalidDimensionException as e:
        raise HTTPException(status_code=500, detail=str(e))

def load_collection_configuration_from_json(
    config_json_map: Dict[str, Any]
) -> CollectionConfiguration:
    if (
        config_json_map.get("spann") is not None
        and config_json_map.get("hnsw") is not None
    ):
        raise ValueError("hnsw and spann cannot both be provided")

    hnsw_config = None
    spann_config = None
    ef_config = None

    # Process vector index configuration (HNSW or SPANN)
    if config_json_map.get("hnsw") is not None:
        hnsw_config = cast(HNSWConfiguration, config_json_map["hnsw"])
    if config_json_map.get("spann") is not None:
        spann_config = cast(SpannConfiguration, config_json_map["spann"])

    # Process embedding function configuration
    if config_json_map.get("embedding_function") is not None:
        ef_config = config_json_map["embedding_function"]
        if ef_config["type"] == "legacy":
            warnings.warn(
                "legacy embedding function config",
                DeprecationWarning,
                stacklevel=2,
            )
            ef = None
        else:
            try:
                ef_name = ef_config["name"]
            except KeyError:
                raise ValueError(
                    f"Embedding function name not found in config: {ef_config}"
                )
            try:
                ef = known_embedding_functions[ef_name]
            except KeyError:
                raise ValueError(
                    f"Embedding function {ef_name} not found. Add @register_embedding_function decorator to the class definition."
                )
            try:
                ef = ef.build_from_config(ef_config["config"])  # type: ignore
            except Exception as e:
                raise ValueError(
                    f"Could not build embedding function {ef_config['name']} from config {ef_config['config']}: {e}"
                )
    else:
        ef = None

    return CollectionConfiguration(
        hnsw=hnsw_config,
        spann=spann_config,
        embedding_function=ef,  # type: ignore
    )

def load_create_collection_configuration_from_json(
    json_map: Dict[str, Any]
) -> CreateCollectionConfiguration:
    if json_map.get("hnsw") is not None and json_map.get("spann") is not None:
        raise ValueError("hnsw and spann cannot both be provided")

    result = CreateCollectionConfiguration()

    # Handle vector index configuration
    if json_map.get("hnsw") is not None:
        result["hnsw"] = json_to_create_hnsw_configuration(json_map["hnsw"])

    if json_map.get("spann") is not None:
        result["spann"] = json_to_create_spann_configuration(json_map["spann"])

    # Handle embedding function configuration
    if json_map.get("embedding_function") is not None:
        ef_config = json_map["embedding_function"]
        if ef_config["type"] == "legacy":
            warnings.warn(
                "legacy embedding function config",
                DeprecationWarning,
                stacklevel=2,
            )
        else:
            ef = known_embedding_functions[ef_config["name"]]
            result["embedding_function"] = ef.build_from_config(ef_config["config"])

    return result

def load_update_collection_configuration_from_json(
    json_map: Dict[str, Any]
) -> UpdateCollectionConfiguration:
    """Convert a JSON dict to an UpdateCollectionConfiguration"""
    if json_map.get("hnsw") is not None and json_map.get("spann") is not None:
        raise ValueError("hnsw and spann cannot both be provided")

    result = UpdateCollectionConfiguration()

    # Handle vector index configurations
    if json_map.get("hnsw") is not None:
        result["hnsw"] = json_to_update_hnsw_configuration(json_map["hnsw"])

    if json_map.get("spann") is not None:
        result["spann"] = json_to_update_spann_configuration(json_map["spann"])

    # Handle embedding function
    if json_map.get("embedding_function") is not None:
        if json_map["embedding_function"]["type"] == "legacy":
            warnings.warn(
                "legacy embedding function config",
                DeprecationWarning,
                stacklevel=2,
            )
        else:
            ef = known_embedding_functions[json_map["embedding_function"]["name"]]
            result["embedding_function"] = ef.build_from_config(
                json_map["embedding_function"]["config"]
            )

    return result

def _embed(self, input: Any, is_query: bool = False) -> Embeddings:
    if self._embedding_function is not None and not isinstance(
        self._embedding_function, DefaultEmbeddingFunction
    ):
        if is_query:
            return self._embedding_function.embed_query(input=input)
        else:
            return self._embedding_function(input=input)

    config_ef = self.configuration.get("embedding_function")
    if config_ef is not None:
        if is_query:
            return config_ef.embed_query(input=input)
        else:
            return config_ef(input=input)
    schema = self.schema
    schema_embedding_function: Optional[EmbeddingFunction[Embeddable]] = None
    if schema is not None:
        override = schema.keys.get(EMBEDDING_KEY)
        if (
            override is not None
            and override.float_list is not None
            and override.float_list.vector_index is not None
            and override.float_list.vector_index.config.embedding_function
            is not None
        ):
            schema_embedding_function = cast(
                EmbeddingFunction[Embeddable],
                override.float_list.vector_index.config.embedding_function,
            )
        elif (
            schema.defaults.float_list is not None
            and schema.defaults.float_list.vector_index is not None
            and schema.defaults.float_list.vector_index.config.embedding_function
            is not None
        ):
            schema_embedding_function = cast(
                EmbeddingFunction[Embeddable],
                schema.defaults.float_list.vector_index.config.embedding_function,
            )

    if schema_embedding_function is not None:
        if is_query and hasattr(schema_embedding_function, "embed_query"):
            return schema_embedding_function.embed_query(input=input)
        return schema_embedding_function(input=input)
    if self._embedding_function is None:
        raise ValueError(
            "You must provide an embedding function to compute embeddings."
            "https://docs.trychroma.com/guides/embeddings"
        )
    if is_query:
        return self._embedding_function.embed_query(input=input)
    else:
        return self._embedding_function(input=input)

def build_from_config(config: Dict[str, Any]) -> "EmbeddingFunction[Documents]":
    model_name = config.get("model_name")
    device = config.get("device")
    normalize_embeddings = config.get("normalize_embeddings")
    kwargs = config.get("kwargs", {})

    if model_name is None or device is None or normalize_embeddings is None:
        assert False, "This code should not be reached"

    return SentenceTransformerEmbeddingFunction(
        model_name=model_name,
        device=device,
        normalize_embeddings=normalize_embeddings,
        **kwargs,
    )

def authorize_or_raise(
    self, user: UserIdentity, action: AuthzAction, resource: AuthzResource
) -> None:
    policy_decision = False
    if (
        user.user_id in self._permissions
        and action in self._permissions[user.user_id]
    ):
        policy_decision = True

    logger.debug(
        f"Authorization decision: Access "
        f"{'granted' if policy_decision else 'denied'} for "
        f"user [{user.user_id}] attempting to "
        f"[{action}] [{resource}]"
    )
    if not policy_decision:
        raise HTTPException(status_code=403, detail="Forbidden")

def _get_collection(self, collection_id: UUID) -> t.Collection:
    collections = self._sysdb.get_collections(id=collection_id)
    if not collections or len(collections) == 0:
        raise NotFoundError(f"Collection {collection_id} does not exist.")
    return collections[0]
